-- Data Communication — Chapter 1 (Real)  (25 questions, from quiz-real-dc-chapter-1.json)
WITH q AS (
  INSERT INTO public.quizzes (title, description, subject, department, year, status, source_type, duration_seconds)
  SELECT 'اتصالات البيانات — الفصل 1 (حقيقي)', '{"description":"Real questions extracted from downloads/data-communication/Chapter_1_Sheet_Solution.pdf (pages p1-53). Questions and solutions are printed in the deck; wrong options are constructed. Actual course content.","department":"AI","year":"المستوى الثاني","subject":"اتصالات البيانات","semester":"1"}', 'اتصالات البيانات', 'AI', 'المستوى الثاني', 'approved', 'manual', 1500
  WHERE NOT EXISTS (SELECT 1 FROM public.quizzes WHERE title = 'اتصالات البيانات — الفصل 1 (حقيقي)')
  RETURNING id
)
INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('Identify the five components of a data communications system.', '["Sender, receiver, transmission medium, message, protocol","Sender, receiver, router, switch, protocol","Message, signal, medium, protocol, port","Sender, receiver, codec, modem, protocol"]'::jsonb, 0, 'Solution slide 1: the five components are sender, receiver, transmission medium, message, protocol. — المصدر: Chapter_1_Sheet_Solution.pdf، صp3-4', 1),
  ('What are the advantages of distributed processing?', '["Security, access to distributed databases, collaborative processing, faster problem solving","Lower bandwidth, simpler protocols, fewer cables","Central control, single point of failure, easy backup","Cheaper hardware, fewer servers, offline work"]'::jsonb, 0, 'Solution slide 2 (verbatim four advantages). — المصدر: Chapter_1_Sheet_Solution.pdf، صp5-6', 2),
  ('What are the three criteria necessary for an effective and efficient network?', '["Performance, reliability, security","Speed, cost, size","Bandwidth, latency, jitter","Hardware, software, firmware"]'::jsonb, 0, 'Solution slide 3. — المصدر: Chapter_1_Sheet_Solution.pdf، صp7-8', 3),
  ('What are the advantages of a multipoint connection over a point-to-point connection?', '["Ease of installation and low cost","Higher speed and reliability","Dedicated bandwidth per device","Simpler protocols"]'::jsonb, 0, 'Solution slide 4. — المصدر: Chapter_1_Sheet_Solution.pdf، صp9-10', 4),
  ('What are the two types of line configuration?', '["Point-to-point and multipoint","Wired and wireless","Serial and parallel","Analog and digital"]'::jsonb, 0, 'Solution slide 5. — المصدر: Chapter_1_Sheet_Solution.pdf، صp11-12', 5),
  ('Categorize the four basic topologies in terms of line configuration.', '["Point-to-point: mesh, star, ring — multipoint: bus","Point-to-point: bus — multipoint: mesh, star, ring","All four are point-to-point","All four are multipoint"]'::jsonb, 0, 'Solution slide 6. — المصدر: Chapter_1_Sheet_Solution.pdf، صp13-14', 6),
  ('What is the difference between half-duplex and full-duplex transmission modes?', '["Half-duplex: only one entity can send at a time; full-duplex: both can send at the same time","Half-duplex is wireless; full-duplex is wired","Half-duplex is faster; full-duplex is slower","Half-duplex uses one cable; full-duplex uses four"]'::jsonb, 0, 'Solution slide 7. — المصدر: Chapter_1_Sheet_Solution.pdf، صp15-16', 7),
  ('Name the four basic network topologies with an advantage of each.', '["Mesh — secure; bus — easy installation; star — robust; ring — easy fault isolation","Mesh — cheap; bus — secure; star — fast; ring — wireless","Mesh — easy installation; bus — secure; star — cheap; ring — fast","Mesh — robust; bus — fault isolation; star — secure; ring — cheap"]'::jsonb, 0, 'Solution slide 8 (verbatim). — المصدر: Chapter_1_Sheet_Solution.pdf، صp17-18', 8),
  ('For n devices in a network, what is the number of cable links required for a mesh, ring, bus, and star topology?', '["Mesh: n(n−1)/2, ring: n−1, bus: one backbone + n drop lines, star: n","Mesh: n−1, ring: n(n−1)/2, bus: n, star: n+1","Mesh: n, ring: n−1, bus: n−1, star: n(n−1)/2","All four need n(n−1)/2 links"]'::jsonb, 0, 'Solution slide 9 (verbatim). — المصدر: Chapter_1_Sheet_Solution.pdf، صp19-20', 9),
  ('What are some of the factors that determine whether a communication system is a LAN or WAN?', '["Size, distances covered by the network, structure, ownership","Only the number of computers","Only the cable type","Only the operating system"]'::jsonb, 0, 'Solution slide 10. — المصدر: Chapter_1_Sheet_Solution.pdf، صp21-22', 10),
  ('What is an internet? What is the Internet?', '["An internet is an interconnection of networks; the Internet is the name of a specific worldwide network","Both are the same thing","An internet is a private LAN; the Internet is a public LAN","An internet is hardware; the Internet is software"]'::jsonb, 0, 'Solution slide 11 (verbatim). — المصدر: Chapter_1_Sheet_Solution.pdf، صp23-24', 11),
  ('Why are protocols needed?', '["A protocol defines what is communicated, in what way, and when — enabling accurate and timely transfer of information","To make networks faster only","To encrypt all traffic","To replace the physical medium"]'::jsonb, 0, 'Solution slide 12. — المصدر: Chapter_1_Sheet_Solution.pdf، صp25-26', 12),
  ('Why are standards needed?', '["To create and maintain an open, competitive market, coordinate protocol rules, and guarantee compatibility","To increase prices","To lock users to one vendor","To eliminate protocols"]'::jsonb, 0, 'Solution slide 13. — المصدر: Chapter_1_Sheet_Solution.pdf، صp27-28', 13),
  ('What is the maximum number of characters or symbols that can be represented by Unicode?', '["2³² = 4,294,967,296","2¹⁶ = 65,536","2⁸ = 256","2⁶⁴"]'::jsonb, 0, 'Solution slide 14: Unicode uses 32 bits per symbol. — المصدر: Chapter_1_Sheet_Solution.pdf، صp30-31', 14),
  ('A color image uses 16 bits to represent a pixel. What is the maximum number of different colors?', '["2¹⁶ = 65,536","2¹⁵ = 32,768","2³² = 4,294,967,296","16"]'::jsonb, 0, 'Solution slide 15. — المصدر: Chapter_1_Sheet_Solution.pdf، صp32-33', 15),
  ('Assume six devices are arranged in a mesh topology. How many cables are needed? How many ports per device?', '["15 cables; 5 ports per device","12 cables; 5 ports per device","15 cables; 6 ports per device","30 cables; 6 ports per device"]'::jsonb, 0, 'Solution slide 16: n(n−1)/2 = 6×5/2 = 15; ports = n−1 = 5. — المصدر: Chapter_1_Sheet_Solution.pdf، صp34-35', 16),
  ('For mesh, star, bus, and ring topologies, what happens if one connection fails?', '["Mesh: other links continue; star: only the affected device loses access; bus: backbone failure stops transmission; ring: may disable the network","All four topologies stop completely","Only mesh is affected","Only bus continues working"]'::jsonb, 0, 'Solution slide 17 (failure-impact table, verbatim). — المصدر: Chapter_1_Sheet_Solution.pdf، صp36-37', 17),
  ('Two computers are connected by an Ethernet hub at home. Is this a LAN, MAN, or WAN?', '["A LAN","A MAN","A WAN","Neither — it is a PAN only"]'::jsonb, 0, 'Solution slide 18: an Ethernet hub creates a local area network. — المصدر: Chapter_1_Sheet_Solution.pdf، صp38-39', 18),
  ('In the ring topology, what happens if one of the stations is unplugged?', '["Theoretically the ring is interrupted; most ring networks use a bypass mechanism so the ring keeps operating","Nothing ever happens","All stations stop permanently with no workaround","Only that station slows down"]'::jsonb, 0, 'Solution slide 19. — المصدر: Chapter_1_Sheet_Solution.pdf، صp40-41', 19),
  ('In the bus topology, what happens if one of the stations is unplugged?', '["No effect — no station is in the path of the signal","The whole network stops","Only the neighbors fail","The backbone must be replaced"]'::jsonb, 0, 'Solution slide 20. — المصدر: Chapter_1_Sheet_Solution.pdf، صp42-43', 20),
  ('Draw a hybrid topology with a star backbone and three ring networks — what does it look like?', '["A star backbone connecting three separate ring segments","A ring backbone connecting three stars","Three buses on one ring","A mesh of three rings"]'::jsonb, 0, 'Solution slide 21. — المصدر: Chapter_1_Sheet_Solution.pdf، صp44-45', 21),
  ('Draw a hybrid topology with a ring backbone and two bus networks — what does it look like?', '["A ring backbone connecting two bus segments (hybrid ring–bus)","A star backbone with two rings","A bus backbone with two rings","A full mesh of buses"]'::jsonb, 0, 'Solution slide 22. — المصدر: Chapter_1_Sheet_Solution.pdf، صp46-47', 22),
  ('Which application is more sensitive to delay: e-mail, file copying, or surfing the Internet?', '["Web surfing — users expect timely access to the requested site","E-mail","File copying","All three are equally sensitive"]'::jsonb, 0, 'Solution slide 23: e-mail and file copy are not very delay-sensitive; web surfing is. — المصدر: Chapter_1_Sheet_Solution.pdf، صp48-49', 23),
  ('When a party makes a local telephone call to another party, is this a point-to-point or multipoint connection?', '["Point-to-point — a dedicated line between caller and callee","Multipoint","Broadcast","Neither"]'::jsonb, 0, 'Solution slide 24. — المصدر: Chapter_1_Sheet_Solution.pdf، صp50-51', 24),
  ('Compare the telephone network and the Internet: similarities and differences?', '["Both are interconnections of smaller networks; the telephone network was designed for voice and is mostly circuit-switched, the Internet for data and mostly packet-switched","They share nothing","Both are circuit-switched only","The Internet is circuit-switched; the telephone network is packet-switched"]'::jsonb, 0, 'Solution slide 25. — المصدر: Chapter_1_Sheet_Solution.pdf، صp52-53', 25)
) AS v(question, options, correct_answer, explanation, order_index);

-- Data Communication — Chapter 2 MCQ (Real)  (21 questions, from quiz-real-dc-chapter-2.json)
WITH q AS (
  INSERT INTO public.quizzes (title, description, subject, department, year, status, source_type, duration_seconds)
  SELECT 'اتصالات البيانات — الفصل 2 اختيار من متعدد (حقيقي)', '{"description":"Real questions extracted from downloads/data-communication/Chapter_2_Solutions.pdf (pages p69-111). Questions, options, and answers are printed verbatim in the deck. Actual course content.","department":"AI","year":"المستوى الثاني","subject":"اتصالات البيانات","semester":"1"}', 'اتصالات البيانات', 'AI', 'المستوى الثاني', 'approved', 'manual', 1260
  WHERE NOT EXISTS (SELECT 1 FROM public.quizzes WHERE title = 'اتصالات البيانات — الفصل 2 اختيار من متعدد (حقيقي)')
  RETURNING id
)
INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('The TCP/IP protocol suite consists of _______ layers.', '["two","three","five","six"]'::jsonb, 2, 'Printed answer: C) five. — المصدر: Chapter_2_Solutions.pdf، صp70-71', 1),
  ('A router is involved in ____________ layers of the TCP/IP protocol suite.', '["two","three","four","five"]'::jsonb, 1, 'Printed answer: B) three. — المصدر: Chapter_2_Solutions.pdf، صp72-73', 2),
  ('A link-layer switch is involved in ____________ layers of the TCP/IP protocol suite.', '["two","three","four","five"]'::jsonb, 0, 'Printed answer: A) two. — المصدر: Chapter_2_Solutions.pdf، صp74-75', 3),
  ('In the TCP/IP protocol suite, which of the following is an application layer protocol?', '["The User Datagram Protocol (UDP)","The Internet Protocol (IP)","The File Transfer Protocol (FTP)","The Transmission Control Protocol (TCP)"]'::jsonb, 2, 'Printed answer: C) FTP. — المصدر: Chapter_2_Solutions.pdf، صp76-77', 4),
  ('In the TCP/IP protocol suite, which of the following is a transport-layer protocol?', '["The Internet Control Message Protocol (ICMP)","The Internet Protocol (IP)","The Address Resolution Protocol (ARP)","The Transmission Control Protocol (TCP)"]'::jsonb, 3, 'Printed answer: D) TCP. — المصدر: Chapter_2_Solutions.pdf، صp78-79', 5),
  ('In the TCP/IP protocol suite, which of the following is a network layer protocol?', '["The Stream Control Transmission Protocol (SCTP)","The Secure Shell (SSH)","The Internet Protocol (IP)","User Datagram Protocol (UDP)"]'::jsonb, 2, 'Printed answer: C) IP. — المصدر: Chapter_2_Solutions.pdf، صp80-81', 6),
  ('The transport-layer packet in the TCP/IP protocol suite is called _______________.', '["a message","a datagram","a segment or a user datagram","a frame"]'::jsonb, 2, 'Printed answer: C) a segment or a user datagram. — المصدر: Chapter_2_Solutions.pdf، صp82-83', 7),
  ('In the TCP/IP protocol suite, the ______ layer is responsible for moving frames from one hop (node) to the next.', '["physical","data-link","transport","network"]'::jsonb, 1, 'Printed answer: B) data-link. — المصدر: Chapter_2_Solutions.pdf، صp84-85', 8),
  ('In the TCP/IP protocol suite, the physical layer is concerned with the movement of _______ over the physical medium.', '["programs","dialogs","protocols","bits"]'::jsonb, 3, 'Printed answer: D) bits. — المصدر: Chapter_2_Solutions.pdf، صp86-87', 9),
  ('In the TCP/IP protocol suite, a port number is the identifier at the ____________.', '["application layer","transport layer","network layer","physical layer"]'::jsonb, 1, 'Printed answer: B) transport layer. — المصدر: Chapter_2_Solutions.pdf، صp88-89', 10),
  ('In the TCP/IP protocol suite, a logical address is the identifier at the _________.', '["network layer","transport layer","data-link layer","application layer"]'::jsonb, 0, 'Printed answer: A) network layer. — المصدر: Chapter_2_Solutions.pdf، صp90-91', 11),
  ('The _________ layer is responsible for the delivery of a message from one process to another.', '["physical","transport","network","application"]'::jsonb, 1, 'Printed answer: B) transport. — المصدر: Chapter_2_Solutions.pdf، صp92-93', 12),
  ('The Internet Protocol (IP) is ________ protocol.', '["a reliable","a connection-oriented","a reliable and connection-oriented","an unreliable"]'::jsonb, 3, 'Printed answer: D) an unreliable. — المصدر: Chapter_2_Solutions.pdf، صp94-95', 13),
  ('The application layer in the TCP/IP protocol suite is usually considered to be the combination of ________ layers in the OSI model.', '["application, presentation, and session","application, transport, and network","application, data-link, and physical","network, data-link, and physical"]'::jsonb, 0, 'Printed answer: A) application, presentation, and session. — المصدر: Chapter_2_Solutions.pdf، صp96-97', 14),
  ('In TCP/IP, a message at the application layer is encapsulated in a packet at the ____ layer.', '["network","transport","data-link","physical"]'::jsonb, 1, 'Printed answer: B) transport. — المصدر: Chapter_2_Solutions.pdf، صp98-99', 15),
  ('In TCP/IP, a message at the transport layer is encapsulated in a packet at the ________ layer.', '["network","transport","data-link","physical"]'::jsonb, 0, 'Printed answer: A) network. — المصدر: Chapter_2_Solutions.pdf، صp100-101', 16),
  ('In TCP/IP, a message belonging to the network layer is decapsulated from a packet at the ________ layer.', '["network","transport","data-link","physical"]'::jsonb, 2, 'Printed answer: C) data-link. — المصدر: Chapter_2_Solutions.pdf، صp102-103', 17),
  ('In TCP/IP, a message belonging to the transport layer is decapsulated from a packet at the ________ layer.', '["network","transport","data-link","physical"]'::jsonb, 0, 'Printed answer: A) network. — المصدر: Chapter_2_Solutions.pdf، صp104-105', 18),
  ('In TCP/IP, a logical connection between an entity at the network layer can be made with another entity at the ________ layer.', '["network","transport","data-link","physical"]'::jsonb, 0, 'Printed answer: A) network. — المصدر: Chapter_2_Solutions.pdf، صp106-107', 19),
  ('In TCP/IP, a logical connection between an entity at the data-link layer can be made with another entity at the ________ layer.', '["network","transport","data-link","physical"]'::jsonb, 2, 'Printed answer: C) data-link. — المصدر: Chapter_2_Solutions.pdf، صp108-109', 20),
  ('In TCP/IP, a packet at the third layer carries data belonging to the ________ layer and the header belonging to the _________ layer.', '["third; third","third; fourth","fourth; third","fourth; fourth"]'::jsonb, 2, 'Printed answer: C) fourth; third. — المصدر: Chapter_2_Solutions.pdf، صp110-111', 21)
) AS v(question, options, correct_answer, explanation, order_index);

-- Data Communication — Chapter 3 (Real)  (17 questions, from quiz-real-dc-chapter-3.json)
WITH q AS (
  INSERT INTO public.quizzes (title, description, subject, department, year, status, source_type, duration_seconds)
  SELECT 'اتصالات البيانات — الفصل 3 (حقيقي)', '{"description":"Real questions extracted from downloads/data-communication/Chapter_3_Data_and_Signal.pdf (Data and Signals — question + step-by-step solution slides). Questions and answers verbatim from the deck; wrong options constructed.","department":"AI","year":"المستوى الثاني","subject":"اتصالات البيانات","semester":"1"}', 'اتصالات البيانات', 'AI', 'المستوى الثاني', 'approved', 'manual', 1020
  WHERE NOT EXISTS (SELECT 1 FROM public.quizzes WHERE title = 'اتصالات البيانات — الفصل 3 (حقيقي)')
  RETURNING id
)
INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('What is the relationship between frequency and period?', '["They are the inverse of each other: T = 1/f and f = 1/T (period in seconds, frequency in Hz)","They are equal","Frequency is period squared","Period is frequency times 2π"]'::jsonb, 0, 'Solution 1: inverse relationship; T = 1/f and f = 1/T; units s vs Hz. — المصدر: Chapter_3_Data_and_Signal.pdf، صp2-3', 1),
  ('What does the amplitude, frequency, and phase of a signal measure?', '["Amplitude: signal value/strength; frequency: number of periods per second; phase: position of the waveform relative to time zero","Amplitude: speed; frequency: strength; phase: color","Amplitude: number of cycles; frequency: amplitude; phase: duration","All three measure the same thing"]'::jsonb, 0, 'Solution 2 (verbatim). — المصدر: Chapter_3_Data_and_Signal.pdf، صp4-5', 2),
  ('How can a composite signal be decomposed into its individual frequencies?', '["Fourier analysis — Fourier series (discrete, periodic) and Fourier transform (continuous, nonperiodic)","Ohm''s law","Nyquist sampling","Shannon''s theorem"]'::jsonb, 0, 'Solution 3 (verbatim). — المصدر: Chapter_3_Data_and_Signal.pdf، صp6-7', 3),
  ('Name the three types of transmission impairment.', '["Attenuation, distortion, noise","Jitter, echo, crosstalk","Delay, loss, gain","Interference, reflection, refraction"]'::jsonb, 0, 'Solution 4: attenuation (energy loss), distortion (shape change from different propagation speeds), noise (external corrupting signals). — المصدر: Chapter_3_Data_and_Signal.pdf، صp8-9', 4),
  ('Distinguish between baseband and broadband transmission.', '["Baseband: sending a signal without modulation via a low-pass channel; broadband: modulating a signal onto a carrier using a band-pass channel","Baseband uses modulation; broadband does not","Baseband is wireless; broadband is wired","They are identical"]'::jsonb, 0, 'Solution 5 (verbatim). — المصدر: Chapter_3_Data_and_Signal.pdf، صp10-11', 5),
  ('What does the Nyquist theorem define?', '["The maximum theoretical bit rate of a noiseless channel: BitRate = 2 × B × log₂(L)","The maximum bit rate of a noisy channel","The speed of light in copper","The number of harmonics in a square wave"]'::jsonb, 0, 'Solution 7 (verbatim). — المصدر: Chapter_3_Data_and_Signal.pdf، صp12-13', 6),
  ('What does the Shannon capacity determine?', '["The theoretical maximum bit rate of a noisy channel: Capacity = B × log₂(1 + SNR)","The bit rate of a noiseless channel","The attenuation of a cable","The phase of a signal"]'::jsonb, 0, 'Solution 8 (verbatim). — المصدر: Chapter_3_Data_and_Signal.pdf، صp12-13', 7),
  ('(P3-16) Calculate the corresponding periods for: a. f = 24 Hz, b. f = 8 MHz, c. f = 140 kHz (T = 1/f).', '["a. 41.7 ms, b. 0.125 µs, c. 7.14 µs","a. 41.7 µs, b. 0.125 ms, c. 7.14 ms","a. 24 s, b. 8 s, c. 140 s","a. 0.0417 ms, b. 1.25 µs, c. 71.4 µs"]'::jsonb, 0, 'Solution 16 (step-by-step, verbatim): T = 1/(24 Hz) = 41.7 ms; T = 1/(8×10⁶) = 0.125 µs; T = 1/(140×10³) = 7.14 µs. — المصدر: Chapter_3_Data_and_Signal.pdf، صp14-15', 8),
  ('(P3-17) Calculate the corresponding frequencies for: a. T = 5 s, b. T = 12 µs, c. T = 220 ns (f = 1/T).', '["a. 0.2 Hz, b. 83.333 kHz, c. 4.55 MHz","a. 5 Hz, b. 12 kHz, c. 220 MHz","a. 0.5 Hz, b. 8.333 kHz, c. 45.5 MHz","a. 2 Hz, b. 83.333 MHz, c. 4.55 GHz"]'::jsonb, 0, 'Solution 17 (verbatim): f = 1/(5 s) = 0.2 Hz; f = 1/(12 µs) = 83.333 kHz; f = 1/(220 ns) = 4.55 MHz. — المصدر: Chapter_3_Data_and_Signal.pdf، صp16-17', 9),
  ('(P3-22) What is the bit rate for each of the following signals? a. 1 bit lasts 0.001 s, b. 1 bit lasts 2 ms, c. 10 bits last 20 µs.', '["a. 1 kbps, b. 500 bps, c. 500 kbps","a. 1000 kbps, b. 500 kbps, c. 50 kbps","a. 1 bps, b. 2 bps, c. 0.5 bps","a. 10 kbps, b. 5 kbps, c. 5 Mbps"]'::jsonb, 0, 'Solution 22 (verbatim): Bit rate = 1/(0.001 s) = 1 kbps; 1/(2 ms) = 500 bps; 10/(20 µs) → bit duration 2 µs → 500 kbps. — المصدر: Chapter_3_Data_and_Signal.pdf، صp18-19', 10),
  ('(P3-24) What is the bit rate for a digital signal that sends 8 bits in 16 ns?', '["500 Mbps","0.5 Mbps","128 Mbps","8 Gbps"]'::jsonb, 0, 'Solution 24 (verbatim): 8 / (16 × 10⁻⁹) = 0.5 × 10⁹ bps = 500 Mbps. — المصدر: Chapter_3_Data_and_Signal.pdf، صp20-21', 11),
  ('(P3-30) Signal power at point A is 100 W and at point B is 90 W. What is the attenuation in dB?', '["−0.46 dB","+0.46 dB","−10 dB","−4.6 dB"]'::jsonb, 0, 'Solution 30 (verbatim): dB = 10 log₁₀(90/100) = −0.46 dB. — المصدر: Chapter_3_Data_and_Signal.pdf، صp22-23', 12),
  ('(P3-31) The attenuation of a signal is −10 dB. What is the final power if the original power is 5 W?', '["0.5 W","5 W","50 W","0.05 W"]'::jsonb, 0, 'Solution 31 (verbatim): −10 = 10 log₁₀(P₂/5) → P₂ = 5 × 10⁻¹ = 0.5 W. — المصدر: Chapter_3_Data_and_Signal.pdf، صp22-23', 13),
  ('(P3-36) A line has SNR = 1000 and bandwidth = 4000 Hz. What is the maximum data rate (Shannon)?', '["≈ 39,866 bps ≈ 40 kbps","≈ 4000 bps","≈ 400 kbps","≈ 4 Mbps"]'::jsonb, 0, 'Solution 36 (verbatim): C = 4000 × log₂(1 + 1000) ≈ 4000 × 9.967 ≈ 39,866 bps. — المصدر: Chapter_3_Data_and_Signal.pdf، صp24-25', 14),
  ('(P3-46) What is the length of a bit on a channel with propagation speed 2×10⁸ m/s and bandwidth: a. 1 Mbps, b. 10 Mbps, c. 100 Mbps?', '["a. 200 m, b. 20 m, c. 2 m","a. 20 m, b. 200 m, c. 2000 m","a. 2 m, b. 20 m, c. 200 m","a. 2000 m, b. 200 m, c. 20 m"]'::jsonb, 0, 'Solution 46 (verbatim): bit length = propagation speed × bit duration → 200 m / 20 m / 2 m. — المصدر: Chapter_3_Data_and_Signal.pdf، صp26-27', 15),
  ('(P3-47) How many bits can fit on a link with a 2 ms delay if bandwidth is: a. 1 Mbps, b. 10 Mbps, c. 100 Mbps?', '["a. 2,000 bits, b. 20,000 bits, c. 200,000 bits","a. 200 bits, b. 2,000 bits, c. 20,000 bits","a. 20,000 bits, b. 200,000 bits, c. 2,000,000 bits","a. 2 bits, b. 20 bits, c. 200 bits"]'::jsonb, 0, 'Solution 47 (verbatim): bits = bandwidth × delay = 10⁶×2×10⁻³ = 2,000; ×10 = 20,000; ×100 = 200,000. — المصدر: Chapter_3_Data_and_Signal.pdf، صp28-29', 16),
  ('(P3-48) Total delay for a 5,000,000-bit frame on a link (10 routers, queuing 2 µs and processing 1 µs each; 2,000 km, speed 2×10⁸ m/s, bandwidth 5 Mbps)?', '["1.010030 s — transmission time is dominant; processing/queuing are negligible","0.010030 s — propagation is dominant","1.000000 s — queuing is dominant","2.010030 s — propagation is dominant"]'::jsonb, 0, 'Solution 48 (verbatim): processing 10 µs + queuing 20 µs + transmission 1 s + propagation 0.01 s = 1.010030 s. — المصدر: Chapter_3_Data_and_Signal.pdf، صp30-31', 17)
) AS v(question, options, correct_answer, explanation, order_index);

