  ('Which of these sentences are propositions? — "5 + 7 = 10."', '["True","False","Not a proposition","Cannot be determined"]'::jsonb, 1, '5 + 7 = 12 ≠ 10 → False. — المصدر: Assignment_1.pdf، صin-file exercise Q1d', 2),
  ('Which of these sentences are propositions? — "x + 2 = 11."', '["True","False","Not a proposition","Cannot be determined"]'::jsonb, 2, 'Contains a free variable; neither true nor false → not a proposition. — المصدر: Assignment_1.pdf، صin-file exercise Q1e', 3),
  ('Determine whether this biconditional is true or false: "1 + 1 = 3 if and only if monkeys can fly."', '["True","False","Not a proposition","True only if monkeys can fly"]'::jsonb, 0, 'F ↔ F is True (both sides false). — المصدر: Assignment_1.pdf، صin-file exercise Q6c', 4),
  ('Determine whether this conditional statement is true or false: "If 1 + 1 = 2, then 2 + 2 = 5."', '["True","False","Not a proposition","Only in binary"]'::jsonb, 1, 'T → F is False. — المصدر: Assignment_1.pdf، صin-file exercise Q7a', 5),
  ('Determine whether this conditional statement is true or false: "If 1 + 1 = 3, then 2 + 2 = 5."', '["True","False","Not a proposition","Undecidable"]'::jsonb, 0, 'F → F is True (vacuously). — المصدر: Assignment_1.pdf، صin-file exercise Q7c', 6),
  ('How many rows appear in a truth table for p → ￢p ?', '["2","4","8","16"]'::jsonb, 0, 'One variable → 2¹ = 2 rows. — المصدر: Assignment_1.pdf، صin-file exercise Q8a', 7),
  ('How many rows appear in a truth table for q ∨ p ∨ ￢s ∨ ￢r ∨ ￢t ∨ u ?', '["64","32","16","6"]'::jsonb, 0, 'Six variables → 2⁶ = 64 rows. — المصدر: Assignment_1.pdf، صin-file exercise Q8c', 8),
  ('Use De Morgan''s laws to find the negation of: "Ibrahim is smart and hard working."', '["Ibrahim is not smart, or he is not hard working.","Ibrahim is not smart, and he is not hard working.","Ibrahim is smart, or he is not hard working.","Ibrahim is neither smart nor hard working."]'::jsonb, 0, '￢(p ∧ q) ≡ ￢p ∨ ￢q. — المصدر: Assignment_1.pdf، صin-file exercise Q12a', 9),
  ('The dual of a compound proposition replaces ∨ by ∧, ∧ by ∨, T by F, F by T. Find the dual of: p ∨ ￢q', '["p ∧ ￢q","p ∨ q","￢p ∧ q","￢p ∨ ￢q"]'::jsonb, 0, 'Only the operator changes: ∨ → ∧. — المصدر: Assignment_1.pdf، صin-file exercise Q20a', 10)
) AS v(question, options, correct_answer, explanation, order_index);

