  ('Let P(x) denote "x ≤ 4". What is the truth value of P(0)?', '["True","False","Undefined","Depends on the domain"]'::jsonb, 0, '0 ≤ 4 → True. — المصدر: Assignment_2.pdf، صin-file exercise Q1a', 1),
  ('Let P(x) denote "x ≤ 4". What is the truth value of P(6)?', '["True","False","Undefined","Depends on the domain"]'::jsonb, 1, '6 ≤ 4 is false. — المصدر: Assignment_2.pdf، صin-file exercise Q1c', 2),
  ('Let P(x) be "the word x contains the letter a." What is P(orange)?', '["True","False","Undefined","Not a proposition"]'::jsonb, 0, '"orange" contains the letter a → True. — المصدر: Assignment_2.pdf، صin-file exercise Q2a', 3),
  ('Let P(x) be "the word x contains the letter a." What is P(lemon)?', '["True","False","Undefined","Not a proposition"]'::jsonb, 1, '"lemon" has no letter a → False. — المصدر: Assignment_2.pdf، صin-file exercise Q2b', 4),
  ('Let P(x) be "x = x²" over the integers. What is P(2)?', '["True","False","Undefined","Only for x ≥ 0"]'::jsonb, 1, '2 ≠ 4 → False. — المصدر: Assignment_2.pdf، صin-file exercise Q5c', 5),
  ('Determine the truth value (domain = all integers): ∀n(n + 1 > n)', '["True","False","True only for positive n","Undecidable"]'::jsonb, 0, 'n + 1 > n holds for every integer. — المصدر: Assignment_2.pdf، صin-file exercise Q6a', 6),
  ('Determine the truth value (domain = all integers): ∃n(2n = 3n)', '["True","False","Only for n > 0","Undecidable"]'::jsonb, 0, 'n = 0 satisfies 2n = 3n → True. — المصدر: Assignment_2.pdf، صin-file exercise Q6b', 7),
  ('Determine the truth value (domain = all real numbers): ∃x(x³ = −1)', '["True","False","No real solution","Undecidable"]'::jsonb, 0, 'x = −1 gives (−1)³ = −1 → True. — المصدر: Assignment_2.pdf، صin-file exercise Q7a', 8),
  ('What rule of inference is used in: "Alice is a mathematics major. Therefore, Alice is either a mathematics major or a computer science major."?', '["Addition","Simplification","Modus ponens","Conjunction"]'::jsonb, 0, 'p therefore p ∨ q is the Addition rule. — المصدر: Assignment_2.pdf، صin-file exercise Q18a', 9),
  ('What rule of inference is used in: "If it is rainy, then the pool will be closed. It is rainy. Therefore, the pool is closed."?', '["Modus ponens","Modus tollens","Hypothetical syllogism","Disjunctive syllogism"]'::jsonb, 0, 'p → q, p therefore q is Modus ponens. — المصدر: Assignment_2.pdf، صin-file exercise Q18c', 10)
) AS v(question, options, correct_answer, explanation, order_index);

