INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('List the members of {x | x is a real number such that x² = 1}.', '["{1, −1}","{1}","{−1}","∅"]'::jsonb, 0, 'x² = 1 has exactly two real solutions. — المصدر: Assignment_3.pdf، صin-file exercise Q1a', 1),
  ('List the members of {x | x is an integer such that x² = 2}.', '["∅","{√2, −√2}","{2, −2}","{1, −1}"]'::jsonb, 0, 'No integer squares to 2 → the empty set. — المصدر: Assignment_3.pdf، صin-file exercise Q1d', 2),
  ('Determine whether these sets are equal: {1, 3, 3, 3, 5, 5, 5, 5, 5} and {5, 3, 1}', '["Equal","Not equal","Equal only if ordered","Cannot be compared"]'::jsonb, 0, 'Sets ignore duplicates and order — both are {1, 3, 5}. — المصدر: Assignment_3.pdf، صin-file exercise Q3a', 3),
  ('Determine whether these sets are equal: {{1}} and {1, {1}}', '["Not equal","Equal","Equal as sets of sets","Depends on notation"]'::jsonb, 0, '{{1}} contains the set {1}; {1, {1}} contains 1 AND {1} — different elements. — المصدر: Assignment_3.pdf، صin-file exercise Q3b', 4),
  ('Find the power set of {a} (a and b are distinct elements).', '["{∅, {a}}","{a}","{{a}}","{∅, {a}, {a, a}}"]'::jsonb, 0, 'Power set of a 1-element set has 2¹ = 2 members. — المصدر: Assignment_3.pdf، صin-file exercise Q7a', 5),
  ('How many members does the power set of {a, b} have?', '["4","2","3","8"]'::jsonb, 0, '2² = 4: ∅, {a}, {b}, {a, b}. — المصدر: Assignment_3.pdf، صin-file exercise Q7b', 6),
  ('Is this function from {a, b, c, d} to itself one-to-one? f(a)=b, f(b)=a, f(c)=c, f(d)=d', '["Yes, it is one-to-one","No, it is not one-to-one","Only f(c) matters","Cannot be determined"]'::jsonb, 0, 'All four images are distinct. — المصدر: Assignment_3.pdf، صin-file exercise Q19a', 7),
  ('Is this function from {a, b, c, d} to itself one-to-one? f(a)=b, f(b)=b, f(c)=d, f(d)=c', '["No, it is not one-to-one","Yes, it is one-to-one","Yes, because c and d differ","Cannot be determined"]'::jsonb, 0, 'f(a) = f(b) = b → two inputs share an image. — المصدر: Assignment_3.pdf، صin-file exercise Q19b', 8),
  ('Is f(n) = n − 1 (from Z to Z) one-to-one?', '["Yes","No","Only for n > 1","Only for negative n"]'::jsonb, 0, 'n − 1 is injective over the integers. — المصدر: Assignment_3.pdf، صin-file exercise Q21a', 9),
  ('Is f(n) = n² + 1 (from Z to Z) one-to-one?', '["No","Yes","Only for n ≥ 0","Only for odd n"]'::jsonb, 0, 'f(−1) = f(1) = 2 → not injective. — المصدر: Assignment_3.pdf، صin-file exercise Q21b', 10)
) AS v(question, options, correct_answer, explanation, order_index);
